<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import WorkspaceSidebar from './WorkspaceSidebar.vue';
import SyncConflictDecision from './SyncConflictDecision.vue';
import SyncBatchWorkspace from './SyncBatchWorkspace.vue';
import type {Resolution} from './sync-resolution';
import CloudDirectoryPicker from './CloudDirectoryPicker.vue';
import {formatBytes} from './format-bytes';
type Config={id:string;name:string;mode:'pull'|'both';local_root:string;remote_root:string;created_at_utc:string};
type Run={id:string;config_id:string;status:string;started_at_utc:string;finished_at_utc:string|null;error:string;step_count:number;confirmed:number};
type Entry={path:string;id:string;directory:boolean;size:string;sha256?:string;observed_at_utc:string};
type Step={ordinal:number;status:string;recorded_at_utc:string;error:string;plan:{action:string;path:string;from?:string;reason?:string;local:Entry|null;remote:Entry|null};result?:unknown};
type Change={side:string;action:string;old:Entry|null;new:Entry|null;detected_at_utc:string};
type Event={sequence:string;kind:string;recorded_at_utc:string;evidence:unknown};
const names:Record<string,string>={running:'执行中',verification_pending:'已执行，等待完整同步复核',complete:'复核完成',failed:'失败',conflict:'存在冲突',interrupted:'进程中断，待核对',unknown:'结果待核对',planned:'已规划',intent:'已准入',confirmed:'已确认',added:'新增',deleted:'删除',replaced:'身份替换',moved:'移动',renamed:'重命名',moved_and_renamed:'移动并重命名',modified:'元数据 / 内容变化',local_mkdir:'新建本地目录',remote_mkdir:'新建网盘目录',local_move:'本地移动 / 改名',remote_move:'网盘移动 / 改名',local_delete:'移除本地项目',remote_delete:'删除网盘项目',download:'下载到本地',upload:'上传到网盘'};
const configs=ref<Config[]>([]),runs=ref<Run[]>([]),selected=ref(''),detail=ref<{run:Run;steps:Step[];events:Event[];events_truncated?:boolean;changes?:Change[];changes_total?:number;change_offset?:number}|null>(null),selectedRun=ref(''),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),serverActive=ref(false),fresh=ref(false),observed=ref(''),formOpen=ref(false),cloudPicker=ref(false),localPicker=ref(false),localBrowse=ref('D:\\'),localView=ref<{path:string;parent:string;directories:{name:string;path:string}[]}|null>(null),filter=ref(''),page=ref(0),ack=ref(false);
const batchDecisions=ref<Resolution[]>([]);
function addToBatch(d:Resolution){if(d.source_run!==selectedRun.value||batchDecisions.value.some(x=>x.id===d.id))return;if(batchDecisions.value.length>=20){error.value='每批最多20项，请先移除已有选择';return}batchDecisions.value.push(d)}
watch(selectedRun,()=>batchDecisions.value=[]);
const changeOffset=ref(0);
const runCursor=ref(''),runNext=ref(''),runMore=ref(false);
const pickerBusy=ref(false);
const form=ref({name:'',mode:'pull' as 'pull'|'both',local_root:'',remote_root:''});
const visible=computed(()=>{const rows=(detail.value?.steps||[]).filter(s=>!filter.value||s.status===filter.value);return rows.slice(page.value*100,(page.value+1)*100)}),matched=computed(()=>(detail.value?.steps||[]).filter(s=>!filter.value||s.status===filter.value).length);
let active=true,generation=0,timer:ReturnType<typeof setInterval>|undefined,controller:AbortController|undefined;
watch(()=>[form.value.mode,form.value.local_root,form.value.remote_root],()=>ack.value=false);
function requireLogin(){location.assign('/login?next=%2Fsync')}
async function api(path:string,body?:unknown){const requestRevision=generation;const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller?.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!active||requestRevision!==generation)throw new DOMException('过期请求','AbortError');if(response.status===401){if(active)location.assign('/login?next=%2Fsync');throw Error('登录已失效')}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'请求失败');return response.json()}
async function refresh(){if(!active||loading.value||busy.value||document.hidden)return;const request=++generation,c=selected.value,run=selectedRun.value;loading.value=true;controller=new AbortController();try{const data=await api('/api/sync/configs');if(!active||request!==generation)return;configs.value=data.configs;serverActive.value=data.active;fresh.value=true;observed.value=new Date().toISOString();if(c){const result=await api('/api/sync/configs/'+c+'/runs'+(runCursor.value?'?before='+encodeURIComponent(runCursor.value):''));if(!active||request!==generation)return;runs.value=result.runs;runNext.value=result.next_before||'';runMore.value=result.has_more===true}if(run){const result=await api('/api/sync/runs/'+run+(changeOffset.value?'?change_offset='+changeOffset.value:''));if(!active||request!==generation)return;detail.value=result}error.value=''}catch(e){if(active&&request===generation){fresh.value=false;error.value=e instanceof Error?e.message:String(e)}}finally{if(request===generation)loading.value=false}}
function choose(id:string){generation++;controller?.abort();loading.value=false;selected.value=id;runCursor.value='';runNext.value='';runMore.value=false;runs.value=[];selectedRun.value='';detail.value=null;void refresh()}
function runPage(cursor:string){generation++;controller?.abort();loading.value=false;runCursor.value=cursor;runs.value=[];void refresh()}
function changePage(offset:number){generation++;controller?.abort();loading.value=false;changeOffset.value=offset;void refresh()}
function openRun(id:string){generation++;controller?.abort();loading.value=false;selectedRun.value=id;changeOffset.value=0;detail.value=null;filter.value='';page.value=0;void refresh()}
async function create(){if(!active||busy.value||pickerBusy.value||serverActive.value||!ack.value)return;busy.value=true;const request=++generation;controller?.abort();controller=new AbortController();try{const result=await api('/api/sync/configs',form.value);if(!active||request!==generation)return;selected.value=result.id;formOpen.value=false;ack.value=false;notice.value='同步关系已保存。手动开始时会先扫描两端并建立差异计划。'}catch(e){if(active&&request===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(active&&request===generation){busy.value=false;loading.value=false;void refresh()}}}
async function start(){if(!active||busy.value||pickerBusy.value||!fresh.value||serverActive.value||!selected.value)return;busy.value=true;const request=++generation,id=selected.value;controller?.abort();controller=new AbortController();try{const result=await api('/api/sync/configs/'+id+'/runs',{});if(!active||request!==generation)return;selectedRun.value=result.id;detail.value=null;notice.value='本次同步已记录并在后台执行，可以离开页面后再查看。'}catch(e){if(active&&request===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(active&&request===generation){busy.value=false;loading.value=false;void refresh()}}}
async function browse(p=localBrowse.value){if(!active||busy.value)return;busy.value=true;const request=++generation;controller?.abort();controller=new AbortController();try{const result=await api('/api/sync/local-directories?path='+encodeURIComponent(p));if(!active||request!==generation)return;localView.value=result;localBrowse.value=result.path;localPicker.value=true}catch(e){if(active&&request===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(active&&request===generation){busy.value=false;loading.value=false}}}
function hide(){active=false;generation++;controller?.abort();loading.value=false;busy.value=false;if(timer)clearInterval(timer)}
function show(){active=true;void refresh();if(timer)clearInterval(timer);timer=setInterval(()=>{void refresh()},2000)}
function visibility(){if(!document.hidden)void refresh()}
onMounted(()=>{document.title='目录同步 · CloudHarbor';show();window.addEventListener('pagehide',hide);window.addEventListener('pageshow',show);document.addEventListener('visibilitychange',visibility)});
onUnmounted(()=>{hide();window.removeEventListener('pagehide',hide);window.removeEventListener('pageshow',show);document.removeEventListener('visibilitychange',visibility)});
</script>
<template><div class="workspace event-workspace folder-sync-workspace"><WorkspaceSidebar active="/sync" @error="error=$event"/><main class="main"><header class="page-header"><div><p class="eyebrow">手动触发 · 两端核对 · 完整记录</p><h1>目录同步</h1><p class="muted">首次合并建档；单向以网盘变化更新本地，双向传播双方变化。冲突保留两端，结果未知不重发。</p></div><button class="button primary" :disabled="busy||serverActive" @click="formOpen=!formOpen">新建同步关系</button></header><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
<section v-if="formOpen" class="sync-card"><h2>选择同步目录</h2><form @submit.prevent="create"><div class="sync-fields"><label>名称<input v-model="form.name" required maxlength="120" :disabled="busy||pickerBusy"/></label><label>同步方向<select v-model="form.mode" :disabled="busy||pickerBusy"><option value="pull">网盘 → 本地</option><option value="both">本地 ↔ 网盘</option></select></label><label>本地目录（服务所在主机）<div class="path-control"><input v-model="form.local_root" required placeholder="D:\同步目录 或 /volume1/sync" :disabled="busy||pickerBusy"/><button type="button" class="button secondary compact" :disabled="busy||pickerBusy" @click="localPicker=!localPicker">选择目录</button></div></label><label>网盘目录<div class="path-control"><input v-model="form.remote_root" required placeholder="/我的同步目录" :disabled="busy||pickerBusy"/><button type="button" class="button secondary compact" :disabled="busy||pickerBusy" @click="cloudPicker=!cloudPicker">选择目录</button></div></label></div>
<div v-if="localPicker" class="sync-picker"><h3>本地目录浏览</h3><div class="path-control"><input v-model="localBrowse" aria-label="本地浏览地址" :disabled="busy||pickerBusy"/><button type="button" class="button secondary compact" :disabled="busy||pickerBusy" @click="browse()">打开</button></div><template v-if="localView"><div class="toolbar"><button type="button" class="button secondary compact" :disabled="busy||pickerBusy" @click="browse(localView.parent)">向上一级</button><button type="button" class="button primary compact" :disabled="busy||pickerBusy" @click="form.local_root=localView.path;localPicker=false;ack=false">选择当前目录</button><span>{{localView.path}}</span></div><ul><li v-for="item in localView.directories" :key="item.path"><button type="button" class="button secondary compact" :disabled="busy||pickerBusy" @click="browse(item.path)">📁 {{item.name}}</button></li></ul></template></div>
<CloudDirectoryPicker v-if="cloudPicker" :initial="form.remote_root||'/'" :disabled="busy" @busy="pickerBusy=$event" @select="form.remote_root=$event;cloudPicker=false;ack=false" @close="cloudPicker=false" @authentication-required="requireLogin" @unknown="error='目录创建结果待核对，请查看远端操作记录';cloudPicker=false"/>
<p class="muted">本地目录与网盘目录需已存在，不能与监控下载目录、账号状态或其他同步关系重叠。文件覆盖前保留旧内容；删除根据成功基线传播，目录只在为空时移除。</p><label class="sync-ack"><input v-model="ack" type="checkbox" :disabled="busy||pickerBusy"/>我已核对目录和方向；后续同步可能将一端的删除传播到另一端。</label><div class="toolbar"><button class="button primary" :disabled="busy||pickerBusy||serverActive||!ack">{{busy?'处理中…':'保存同步关系'}}</button><button class="button secondary" type="button" :disabled="busy||pickerBusy" @click="formOpen=false">取消</button></div></form></section>
<p class="muted">首次建立内容摘要可能读取远端文件，消耗下载带宽；后续复用身份与元数据一致的摘要，仅对变化重新核对。大目录同步可能耗时较长，可离页后查看记录。</p><section class="sync-card"><div class="section-heading"><h2>同步关系</h2><button class="button secondary compact" :disabled="busy||loading" @click="refresh">刷新记录</button></div><div class="table-wrap" role="region" aria-label="同步关系列表，可横向滚动" tabindex="0"><table class="sync-configs"><thead><tr><th>名称 / 网盘目录</th><th>本地目录</th><th>方向</th><th>操作</th></tr></thead><tbody><tr v-for="item in configs" :key="item.id" :class="{selected:selected===item.id}"><td><strong>{{item.name}}</strong><small>{{item.remote_root}}</small></td><td :title="item.local_root">{{item.local_root}}</td><td>{{item.mode==='pull'?'网盘 → 本地':'双向同步'}}</td><td><button class="button secondary compact" :disabled="busy||pickerBusy" @click="choose(item.id)">查看 / 同步</button></td></tr><tr v-if="!configs.length"><td colspan="4">{{loading?'正在读取同步关系…':fresh?'尚未创建同步关系。':'同步关系列表尚未核对。'}}</td></tr></tbody></table></div><p v-if="observed" class="muted">本页读取 UTC：{{observed}}{{fresh?'':'；保留上次结果，当前读取失败。'}}</p></section>
<section v-if="selected" class="sync-card"><div class="section-heading"><h2>同步批次</h2><p class="muted" data-testid="sync-execution-hint">此操作会实际执行同步。{{configs.find(c=>c.id===selected)?.mode==='both'?'双向同步会传播两端的新增、修改及删除。':'以网盘为准更新本地，远端删除可能移除对应本地项目。'}}冲突保留两端并记录，结果未知时停止核对。</p><button class="button primary" :disabled="busy||!fresh||serverActive" @click="start">{{serverActive?'已有同步执行中':'立即同步'}}</button></div><p class="muted">先完整扫描再执行；发现冲突时保留两端，不执行本批计划。运行失败或中断不推进成功基线。即使无变化，也会留下运行和复核记录。</p><div class="table-wrap"><table><thead><tr><th>开始 UTC</th><th>状态</th><th>已确认 / 计划</th><th>结束 UTC</th><th>操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td>{{run.started_at_utc}}</td><td><span class="status-pill">{{names[run.status]||run.status}}</span><small v-if="run.error">{{run.error}}</small></td><td>{{run.confirmed}} / {{run.step_count}}</td><td>{{run.finished_at_utc||'—'}}</td><td><button class="button secondary compact" :disabled="busy||pickerBusy" @click="openRun(run.id)">查看明细</button></td></tr><tr v-if="!runs.length"><td colspan="5">尚无已读取的同步批次。</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="busy||loading||!runCursor" @click="runPage('')">回到最新批次</button><button class="button secondary compact" :disabled="busy||loading||!runMore" @click="runPage(runNext)">更早批次</button></div></section>
<SyncBatchWorkspace v-if="detail&&detail.steps.some(step=>step.status==='conflict')" :run="detail.run.id" :decisions="batchDecisions" :disabled="busy||!fresh" :sync-active="serverActive" @remove="id=>batchDecisions=batchDecisions.filter(d=>d.id!==id)" @authentication-required="requireLogin"/><section v-if="detail" class="sync-card"><div class="section-heading"><h2>本次同步明细</h2><a class="button secondary compact" :href="'/directory-analysis?run='+detail.run.id">目录比较 / 冲突分析</a><a class="button secondary compact" :href="'/api/sync/runs/'+detail.run.id+'?export=1'">导出完整记录 JSON</a></div><p class="muted">批次 {{detail.run.id}} · {{names[detail.run.status]||detail.run.status}} · 记录为历史证据，不能代替当前两端状态。</p><h3>本轮检测到的两端变化</h3><p class="muted">与上次成功基线比较，共 {{detail.changes_total||0}} 项。检测结果与下方实际执行步骤分别记录；目录移动可能展开为多项操作。</p><div class="table-wrap"><table><thead><tr><th>来源 / 变化</th><th>原路径</th><th>新路径</th><th>身份</th><th>时间证据 UTC</th></tr></thead><tbody><tr v-for="(change,index) in detail.changes||[]" :key="index"><td>{{change.side==='local'?'本地':'网盘'}} · {{names[change.action]||change.action}}</td><td>{{change.old?.path||'—'}}</td><td>{{change.new?.path||'—'}}</td><td>{{change.old?.id||'—'}} → {{change.new?.id||'—'}}</td><td><small>检测 {{change.detected_at_utc}}</small><small>旧观察 {{change.old?.observed_at_utc||'无旧项目'}}</small><small>新观察 {{change.new?.observed_at_utc||'本轮完整扫描未见'}}</small></td></tr><tr v-if="!detail.changes?.length"><td colspan="5">{{detail.run.status==='running'?'正在扫描，尚未发布差异。':'当前页没有检测变化；早期候选的完整快照仍见JSON导出。'}}</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="loading||changeOffset===0" @click="changePage(Math.max(0,changeOffset-100))">上一页变化</button><button class="button secondary compact" :disabled="loading||changeOffset+100>=(detail.changes_total||0)" @click="changePage(changeOffset+100)">下一页变化</button></div><h3>实际执行步骤</h3><div class="toolbar"><label>状态筛选 <select v-model="filter" @change="page=0"><option value="">全部</option><option v-for="s in ['planned','intent','confirmed','conflict','unknown']" :key="s" :value="s">{{names[s]}}</option></select></label><span>共 {{matched}} 项</span></div><div class="table-wrap"><table><thead><tr><th>动作 / 项目</th><th>来源 → 目标</th><th>大小</th><th>状态 / 记录 UTC</th><th>证据</th></tr></thead><tbody><tr v-for="step in visible" :key="step.ordinal"><td><strong>{{names[step.plan.action]||step.plan.action}}</strong><small>{{step.plan.path}}</small><small>{{step.plan.reason}}</small></td><td>{{step.plan.from||step.plan.local?.path||step.plan.remote?.path||'—'}} → {{step.plan.path}}</td><td>{{step.plan.local?.directory||step.plan.remote?.directory?'文件夹':formatBytes(step.plan.local?.size??step.plan.remote?.size)}}</td><td>{{names[step.status]||step.status}}<small>{{step.recorded_at_utc}}</small><small v-if="step.error" class="error-text">{{step.error}}</small></td><td><SyncConflictDecision v-if="step.status==='conflict'" :run="detail.run.id" :ordinal="step.ordinal" :path="step.plan.path" :disabled="busy||!fresh" :sync-active="serverActive" @authentication-required="requireLogin" @add-to-batch="addToBatch"/><details><summary>身份与结果</summary><pre>{{JSON.stringify({local:step.plan.local,remote:step.plan.remote,result:step.result},null,2)}}</pre></details></td></tr><tr v-if="!visible.length"><td colspan="5">{{detail.run.status==='running'?'正在扫描或生成计划…':'当前筛选无逐项操作；无变化运行也保留扫描与基线证据。'}}</td></tr></tbody></table></div><div class="toolbar"><button class="button secondary compact" :disabled="page===0" @click="page--">上一页</button><button class="button secondary compact" :disabled="(page+1)*100>=matched" @click="page++">下一页</button></div><p class="muted">页面时间线展示最近200条，双端快照仅展示数量摘要；导出JSON保留全部事件与完整快照。</p><details><summary>本次同步时间线（{{detail.events.length}} 条）</summary><div class="table-wrap"><table><thead><tr><th>序号</th><th>事件</th><th>本机记录 UTC</th><th>详细证据</th></tr></thead><tbody><tr v-for="event in detail.events" :key="event.sequence"><td>{{event.sequence}}</td><td>{{event.kind}}</td><td>{{event.recorded_at_utc}}</td><td><details><summary>展开</summary><pre>{{JSON.stringify(event.evidence,null,2)}}</pre></details></td></tr></tbody></table></div></details></section>
</main></div></template>
<style scoped>
.sync-card{background:var(--surface,#fff);border:1px solid #e0e6ef;border-radius:12px;padding:20px;margin:18px 0}.sync-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.sync-fields label{display:grid;gap:7px}.path-control,.toolbar,.section-heading{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.section-heading{justify-content:space-between}.section-heading h2{margin:0}.path-control input{flex:1;min-width:150px}input:not([type=checkbox]),select{font:inherit;padding:8px 10px;border:1px solid #cbd5e1;border-radius:7px;max-width:100%;box-sizing:border-box}.sync-ack{display:flex;align-items:center;gap:8px;margin:14px 0}.toolbar{margin:12px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;min-width:600px}th,td{padding:10px 12px;border-bottom:1px solid #e6ebf2;vertical-align:top}th{font-size:12px;background:#f5f7fb;white-space:nowrap}td{font-size:13px;overflow-wrap:anywhere}small{display:block;color:#66758b;margin-top:4px;font-size:12px}.selected{background:#eef5ff}.sync-picker{border:1px solid #d6dfec;padding:14px;border-radius:9px;margin-top:14px}.sync-picker ul{list-style:none;padding:0;max-height:260px;overflow:auto}.sync-picker li{margin:6px 0}pre{max-width:650px;max-height:320px;overflow:auto;font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}.error-text{color:#a33335}summary{cursor:pointer;color:#245cba}@media(max-width:760px){.sync-fields{grid-template-columns:1fr}.sync-card{padding:14px}}
/* 390px real UI review found a 78px local-path column inflated rows to
   333px. Keep both path columns readable and scroll only this table. */
.sync-configs{min-width:880px}
.sync-configs th:nth-child(1),.sync-configs th:nth-child(2){width:36%}
.sync-configs th:nth-child(3),.sync-configs th:nth-child(4){width:14%}
.table-wrap[role=region]:focus-visible{outline:3px solid #b5c9ff;outline-offset:3px}
</style>
